            int dcidLen = w[p++] & 255;
            if (dcidLen > 20 || w.length - p < dcidLen) {
                return null;
            }
            env.dcid = Arrays.copyOfRange(w, p, p + dcidLen);
            p += dcidLen;
            if (p >= w.length) {
                return null;
            }
            int scidLen = w[p++] & 255;
