        int width = 1 << (b >>> 6);
        if (width > w.length - p) {
            return null;
        }
        long v = b & 0x3fL;
        for (int i = 1; i < width; i++) {
            v = (v << 8) | (w[p + i] & 255L);
        }
        return new long[] {v, p + width};
    }

    /** Closest nonnegative integer congruent to raw modulo 2^(8*width); ties pick the larger. */
    static long reconstruct(long raw, int width, long expected) {
        long modulus = 1L << (8 * width);
        long delta = expected - raw;
        long k = Math.floorDiv(delta, modulus);
        if (k < 0) {
            k = 0;
        }
        long low = raw + k * modulus;
        long high = low + modulus;
        long dLow = Math.abs(expected - low);
        long dHigh = high - expected;
        return dHigh <= dLow ? high : low;
    }

    private long expected(int level) {
