    private void accept(int level, long pn, Long epoch) {
        final Set<Long> set = seen.get(level);
        final long value = pn;
        set.add(value);
        journal.add(new Runnable() {
            @Override
            public void run() {
                set.remove(value);
            }
        });
        if (pn > largest[level]) {
            final int lvl = level;
            final long old = largest[level];
            largest[level] = pn;
            journal.add(new Runnable() {
                @Override
                public void run() {
                    largest[lvl] = old;
                }
            });
        }
        if (level != 2 || epoch == null) {
            return;
        }
        long[] st = epochs.get(epoch);
        if (st == null) {
            st = new long[] {pn, pn, 1};
            final long key = epoch;
            epochs.put(key, st);
            journal.add(new Runnable() {
                @Override
                public void run() {
                    epochs.remove(key);
                }
            });
        } else {
            final long[] f = st;
            final long oMin = f[0];
            final long oMax = f[1];
            final long oCount = f[2];
            journal.add(new Runnable() {
                @Override
                public void run() {
                    f[0] = oMin;
                    f[1] = oMax;
                    f[2] = oCount;
                }
            });
            if (pn < st[0]) {
                st[0] = pn;
            }
            if (pn > st[1]) {
                st[1] = pn;
            }
            st[2]++;
        }
        if (epoch == scal[S_EPOCH] + 1) {
            setScalar(S_EPOCH, epoch);
        }
    }

    // ------------------------------------------------------------------ frames

    private boolean frameAudit(Env env, int dcidSeq) {
        byte[] payload = env.payload;
        if (payload.length == 0) {
            throw new WireException(FRAME_ENCODING_ERROR, 0);
        }
        int p = 0;
        while (p < payload.length) {
            int fs = p;
            Frame f = parse(payload, p, env.level, fs);
            frames.add(f);
            apply(f, env.level, fs, dcidSeq);
            p = f.end;
            if (f.type == 0x1c || f.type == 0x1d) {
                closeOffsetOfFrame = fs;
                return true;
            }
        }
        return false;
    }

    private final class Cursor {
        final byte[] data;
        int p;
        final int fs;

        Cursor(byte[] data, int p, int fs) {
            this.data = data;
            this.p = p;
            this.fs = fs;
        }

        long vi() {
            if (p >= data.length) {
                throw err();
            }
            int b = data[p++] & 255;
            int width = 1 << (b >>> 6);
            if (width > data.length - p) {
                throw err();
            }
            long v = b & 0x3fL;
            for (int i = 1; i < width; i++) {
                v = (v << 8) | (data[p++] & 255L);
            }
            return v;
        }

        int one() {
            if (p >= data.length) {
                throw err();
            }
            return data[p++] & 255;
        }

        byte[] take(long n) {
            if (n < 0 || n > data.length - p) {
                throw err();
            }
            int k = (int) n;
            byte[] out = Arrays.copyOfRange(data, p, p + k);
            p += k;
            return out;
        }

        byte[] rest() {
            return take(data.length - p);
        }

        WireException err() {
            return new WireException(FRAME_ENCODING_ERROR, fs);
        }
    }

    private Frame parse(byte[] payload, int p, int level, int fs) {
        int b0 = payload[p] & 255;
        int width = 1 << (b0 >>> 6);
        if (width > payload.length - p) {
            throw new WireException(FRAME_ENCODING_ERROR, fs);
        }
        long type = b0 & 0x3fL;
        for (int i = 1; i < width; i++) {
            type = (type << 8) | (payload[p + i] & 255L);
        }
        if (width != 1 || !KNOWN[(int) type]) {
            throw new WireException(FRAME_ENCODING_ERROR, fs);
        }
        if (type == 0x07 || type == 0x1e) {
            throw new WireException(PROTOCOL_VIOLATION, fs);
        }
        if (level != 2 && APP_ONLY[(int) type]) {
            throw new WireException(PROTOCOL_VIOLATION, fs);
        }
        Frame f = Frame.of(type);
        Cursor c = new Cursor(payload, p + width, fs);
        int t = (int) type;
        switch (t) {
            case 0x00:
            case 0x01:
                break;
            case 0x02:
            case 0x03:
                f.v1 = c.vi();
                f.v2 = c.vi();
                long count = c.vi();
                f.v3 = c.vi();
                if (f.v3 > f.v1) {
                    throw c.err();
                }
                long low = f.v1 - f.v3;
                List<Long> pairs = new ArrayList<>();
                List<Long> intervals = new ArrayList<>();
                intervals.add(low);
                intervals.add(f.v1 + 1);
                for (long i = 0; i < count; i++) {
                    long gap = c.vi();
                    long range = c.vi();
                    if (low < gap + 2) {
                        throw c.err();
                    }
                    long high = low - gap - 2;
                    if (range > high) {
                        throw c.err();
                    }
                    pairs.add(gap);
                    pairs.add(range);
                    intervals.add(high - range);
                    intervals.add(high + 1);
                    low = high - range;
                }
                f.pairs = toLongs(pairs);
                f.intervals = toLongs(intervals);
                if (t == 0x03) {
                    f.e0 = c.vi();
                    f.e1 = c.vi();
                    f.e2 = c.vi();
                }
                break;
            case 0x04:
                f.v1 = c.vi();
                f.v2 = c.vi();
                f.v3 = c.vi();
                break;
            case 0x05:
            case 0x11:
            case 0x15:
                f.v1 = c.vi();
                f.v2 = c.vi();
                break;
            case 0x06:
                f.v1 = c.vi();
                f.v2 = c.vi();
                f.data = c.take(f.v2);
                if (f.v1 + f.v2 > MAX62) {
                    throw c.err();
                }
                break;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                f.hasOffset = (t & 4) != 0;
                f.hasLength = (t & 2) != 0;
                f.fin = (t & 1) != 0;
                f.v1 = c.vi();
                f.v2 = f.hasOffset ? c.vi() : 0;
                if (f.hasLength) {
                    f.v3 = c.vi();
                    f.data = c.take(f.v3);
                } else {
                    f.data = c.rest();
                    f.v3 = f.data.length;
                }
                if (f.v2 + f.v3 > MAX62) {
                    throw c.err();
                }
                break;
            case 0x10:
            case 0x12:
            case 0x13:
            case 0x14:
            case 0x16:
            case 0x17:
            case 0x19:
                f.v1 = c.vi();
                if ((t == 0x12 || t == 0x13 || t == 0x16 || t == 0x17) && f.v1 > STREAMS_CAP) {
                    throw c.err();
                }
                break;
            case 0x18:
                f.v1 = c.vi();
                f.v2 = c.vi();
                if (f.v2 > f.v1) {
                    throw c.err();
                }
                f.cidLen = c.one();
                if (f.cidLen < 1 || f.cidLen > 20) {
                    throw c.err();
                }
                f.cid = c.take(f.cidLen);
                f.token = c.take(16);
                break;
            case 0x1a:
            case 0x1b:
                f.data = c.take(8);
                break;
            case 0x1c:
                f.v1 = c.vi();
                f.v2 = c.vi();
                f.v3 = c.vi();
                f.data = c.take(f.v3);
                break;
            case 0x1d:
                f.v1 = c.vi();
                f.v2 = c.vi();
                f.data = c.take(f.v2);
                break;
            case 0x30:
                f.data = c.rest();
                break;
            case 0x31:
                f.v1 = c.vi();
                f.data = c.take(f.v1);
                break;
            default:
                throw new WireException(FRAME_ENCODING_ERROR, fs);
        }
        f.end = c.p;
        return f;
    }

    private static long[] toLongs(List<Long> values) {
        long[] out = new long[values.size()];
        for (int i = 0; i < out.length; i++) {
            out[i] = values.get(i);
        }
        return out;
    }

    private void apply(Frame f, int level, int fs, int dcidSeq) {
        int t = (int) f.type;
        switch (t) {
            case 0x00:
            case 0x01:
                return;
            case 0x02:
            case 0x03:
                for (int i = 0; i < f.intervals.length; i += 2) {
                    ack[level].add(f.intervals[i], f.intervals[i + 1], journal);
                }
                if (t == 0x03) {
                    ecnMax(level * 3, f.e0);
                    ecnMax(level * 3 + 1, f.e1);
                    ecnMax(level * 3 + 2, f.e2);
                }
                return;
            case 0x04:
                reset(f, fs);
                return;
            case 0x05:
                stop(f, fs);
                return;
            case 0x06:
                crypto[level].insert(f.v1, f.data, 0, f.data.length, fs, journal);
                return;
            case 0x08:
            case 0x09:
            case 0x0a:
            case 0x0b:
            case 0x0c:
            case 0x0d:
            case 0x0e:
            case 0x0f:
                stream(f, fs);
                return;
            case 0x10:
                if (f.v1 > scal[S_SEND_MAX_DATA]) {
                    setScalar(S_SEND_MAX_DATA, f.v1);
                }
                return;
            case 0x11:
                maxStreamData(f, fs);
                return;
            case 0x12:
                if (f.v1 > scal[S_SMS_BIDI]) {
                    setScalar(S_SMS_BIDI, f.v1);
                }
                return;
            case 0x13:
                if (f.v1 > scal[S_SMS_UNI]) {
                    setScalar(S_SMS_UNI, f.v1);
                }
                return;
            case 0x14:
            case 0x16:
            case 0x17:
            case 0x1a:
            case 0x1b:
            case 0x30:
            case 0x31:
                return;
            case 0x15:
                resolve(f.v1, true, fs);
                return;
            case 0x18:
                newConnectionId(f, fs);
                return;
            case 0x19:
                retireConnectionId(f, fs, dcidSeq);
                return;
            case 0x1c:
            case 0x1d:
                return;
            default:
                return;
        }
    }

    private void ecnMax(int index, long value) {
        if (value > ecn[index]) {
            final int idx = index;
            final long old = ecn[idx];
            journal.add(new Runnable() {
                @Override
                public void run() {
                    ecn[idx] = old;
                }
            });
            ecn[index] = value;
        }
    }

    private void stream(Frame f, int fs) {
        Stream s = resolve(f.v1, true, fs);
        long end = f.v2 + f.v3;
        if (s.finalSize != null) {
            if (end > s.finalSize || (f.fin && end != s.finalSize)) {
                throw new WireException(FINAL_SIZE_ERROR, fs);
            }
        } else if (f.fin && end < s.high) {
            throw new WireException(FINAL_SIZE_ERROR, fs);
        }
        long candidate = Math.max(s.high, end);
        long used = scal[S_USED] - s.high + candidate;
        if (candidate > limStream || used > limConn) {
            throw new WireException(FLOW_CONTROL_ERROR, fs);
        }
        if (s.resetCode == null) {
            s.bytes.insert(f.v2, f.data, 0, f.data.length, fs, journal);
        }
        touch(s);
        if (f.fin && s.finalSize == null) {
            s.finalSize = end;
        }
        if (candidate != s.high) {
            setScalar(S_USED, used);
            s.high = candidate;
        }
    }

    private void reset(Frame f, int fs) {
        Stream s = resolve(f.v1, true, fs);
        if (s.finalSize != null && s.finalSize != f.v3) {
            throw new WireException(FINAL_SIZE_ERROR, fs);
        }
        if (f.v3 < s.high) {
            throw new WireException(FINAL_SIZE_ERROR, fs);
        }
        long candidate = Math.max(s.high, f.v3);
        long used = scal[S_USED] - s.high + candidate;
        if (candidate > limStream || used > limConn) {
            throw new WireException(FLOW_CONTROL_ERROR, fs);
        }
        touch(s);
        s.finalSize = f.v3;
        if (s.resetCode == null) {
            s.resetCode = f.v2;
        }
        if (candidate != s.high) {
            setScalar(S_USED, used);
            s.high = candidate;
        }
    }

    private void stop(Frame f, int fs) {
        Stream s = resolve(f.v1, false, fs);
        if (s.stopCode == null) {
            touch(s);
            s.stopCode = f.v2;
        }
    }

    private void maxStreamData(Frame f, int fs) {
        Stream s = resolve(f.v1, false, fs);
        if (f.v2 > s.sendMax) {
            touch(s);
            s.sendMax = f.v2;
        }
    }

    private void newConnectionId(Frame f, int fs) {
        PeerCid known = peer.get(f.v1);
        if (known != null) {
            if (!Arrays.equals(known.cid, f.cid) || !Arrays.equals(known.token, f.token)) {
                throw new WireException(PROTOCOL_VIOLATION, fs);
            }
        } else {
            for (PeerCid pc : peer.values()) {
                if (Arrays.equals(pc.cid, f.cid)) {
                    throw new WireException(PROTOCOL_VIOLATION, fs);
                }
            }
        }
        long oldThreshold = scal[S_THRESHOLD];
        long newThreshold = Math.max(oldThreshold, f.v2);
        boolean fresh = known == null;
        if (newThreshold > oldThreshold) {
            long removed = countObserved(oldThreshold, newThreshold);
            setScalar(S_THRESHOLD, newThreshold);
            setScalar(S_ACTIVE, scal[S_ACTIVE] - removed);
        }
        if (fresh) {
            final long seq = f.v1;
            peer.put(seq, new PeerCid(f.cid, f.token));
            journal.add(new Runnable() {
                @Override
                public void run() {
                    peer.remove(seq);
                }
            });
            if (seq >= scal[S_THRESHOLD]) {
                setScalar(S_ACTIVE, scal[S_ACTIVE] + 1);
            }
        }
        if (scal[S_ACTIVE] > limCids) {
            throw new WireException(CONNECTION_ID_LIMIT_ERROR, fs);
        }
    }

    private long countObserved(long from, long to) {
        long count = 0;
        for (Long s : peer.tailMap(from, true).keySet()) {
            if (s >= to) {
                break;
            }
            count++;
        }
        return count;
    }

    private void retireConnectionId(Frame f, int fs, int dcidSeq) {
        if (f.v1 >= localCids.length || f.v1 == dcidSeq) {
            throw new WireException(PROTOCOL_VIOLATION, fs);
        }
        if (retiredLocal.add(f.v1)) {
            final long value = f.v1;
            journal.add(new Runnable() {
                @Override
                public void run() {
                    retiredLocal.remove(value);
                }
            });
        }
    }

    private Stream resolve(long id, boolean receive, int fs) {
        int category = (int) (id & 3);
        long index = id >>> 2;
        switch (category) {
            case 0:
                if (index >= limBidi) {
                    throw new WireException(STREAM_LIMIT_ERROR, fs);
                }
                if (index + 1 > scal[S_OPEN_BIDI]) {
                    setScalar(S_OPEN_BIDI, index + 1);
                }
                break;
            case 1:
                if (index >= localBidi) {
                    throw new WireException(STREAM_STATE_ERROR, fs);
                }
                break;
            case 2:
                if (!receive) {
                    throw new WireException(STREAM_STATE_ERROR, fs);
                }
                if (index >= limUni) {
                    throw new WireException(STREAM_LIMIT_ERROR, fs);
                }
                if (index + 1 > scal[S_OPEN_UNI]) {
                    setScalar(S_OPEN_UNI, index + 1);
                }
                break;
            default:
                if (receive || index >= localUni) {
                    throw new WireException(STREAM_STATE_ERROR, fs);
                }
                break;
        }
        Stream s = streams.get(id);
        if (s == null) {
            s = new Stream(id);
            streams.put(id, s);
            final long key = id;
            journal.add(new Runnable() {
                @Override
                public void run() {
                    streams.remove(key);
                }
            });
        }
        return s;
    }

    private void touch(final Stream s) {
        final long high = s.high;
        final long sendMax = s.sendMax;
        final Long finalSize = s.finalSize;
        final Long resetCode = s.resetCode;
        final Long stopCode = s.stopCode;
        journal.add(new Runnable() {
            @Override
            public void run() {
                s.high = high;
                s.sendMax = sendMax;
                s.finalSize = finalSize;
                s.resetCode = resetCode;
                s.stopCode = stopCode;
            }
        });
    }

    private void setScalar(int index, long value) {
        long old = scal[index];
        if (old == value) {
            return;
        }
        final int idx = index;
        final long previous = old;
        journal.add(new Runnable() {
            @Override
            public void run() {
                scal[idx] = previous;
            }
        });
        scal[index] = value;
    }

    // ------------------------------------------------------------------ canonical wire

    private byte[] canonical(Env env, long pn, long expectedBefore) {
        ByteArrayOutputStream payload = new ByteArrayOutputStream();
        for (int i = 0; i < frames.size(); i++) {
            byte[] encoded = Frame.encode(frames.get(i));
            payload.write(encoded, 0, encoded.length);
        }
        byte[] body = payload.toByteArray();
        int width = pnWidth(pn, expectedBefore);
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        if (env.level == 2) {
            out.write(0x40 | (env.phase << 2) | (width - 1));
            out.write(env.dcid, 0, env.dcid.length);
        } else {
            out.write((env.level == 0 ? 0xc0 : 0xe0) | (width - 1));
            out.write(new byte[] {0, 0, 0, 1}, 0, 4);
            out.write(env.dcid.length);
            out.write(env.dcid, 0, env.dcid.length);
            out.write(env.scid.length);
            out.write(env.scid, 0, env.scid.length);
            if (env.level == 0) {
                writeVarint(out, env.token.length);
                out.write(env.token, 0, env.token.length);
            }
            writeVarint(out, (long) width + body.length);
        }
        for (int i = width - 1; i >= 0; i--) {
            out.write((int) ((pn >>> (8 * i)) & 255));
        }
        out.write(body, 0, body.length);
        return out.toByteArray();
    }

    private static void writeVarint(ByteArrayOutputStream out, long value) {
        byte[] encoded = de.rub.nds.tlsattacker.core.quic.util.VariableLengthIntegerEncoding
                .encodeVariableLengthInteger(value);
        out.write(encoded, 0, encoded.length);
    }

    private static int pnWidth(long pn, long expected) {
        for (int w = 1; w <= 4; w++) {
            long mask = (1L << (8 * w)) - 1;
            if (reconstruct(pn & mask, w, expected) == pn) {
                return w;
            }
        }
        return 4;
    }

    // ------------------------------------------------------------------ output

    private Map<String, Object> output() {
        Map<String, Object> result = Main.object("packets", packetRows, "datagrams", datagramRows,
                "closed", closedRow(), "keys", keyRow(), "received", receivedRow(), "key_epoch",
                scal[S_EPOCH], "epochs", epochRows(), "opened",
                Main.object("bidi", scal[S_OPEN_BIDI], "uni", scal[S_OPEN_UNI]), "used",
                scal[S_USED], "send_max_data", scal[S_SEND_MAX_DATA], "send_max_streams",
                Main.object("bidi", scal[S_SMS_BIDI], "uni", scal[S_SMS_UNI]), "streams",
                streamRows(), "crypto", cryptoRows(), "acknowledged", ackRows(), "peer_cids",
                peerRows(), "retire_prior_to", scal[S_THRESHOLD], "retired_local",
                retiredRows());
        return result;
    }

    private Object closedRow() {
        if (!closed) {
            return null;
        }
        return Main.object("event", closeEvent, "packet", closePacket, "offset", closeOffset, "code",
                closeCode);
    }

    private List<Object> keyRow() {
        List<Object> out = new ArrayList<>(3);
        if (key[0]) {
            out.add("I");
        }
        if (key[1]) {
            out.add("H");
        }
        if (key[2]) {
            out.add("A");
        }
        return out;
    }

    private Map<String, Object> receivedRow() {
        Map<String, Object> out = Main.object();
        for (int l = 0; l < 3; l++) {
            out.put(LEVEL[l], largest[l] < 0 ? null : (Object) Long.valueOf(largest[l]));
        }
        return out;
    }

    private List<Object> epochRows() {
        List<Object> out = new ArrayList<>(epochs.size());
        for (Map.Entry<Long, long[]> en : epochs.entrySet()) {
            long[] st = en.getValue();
            out.add(Main.object("epoch", en.getKey(), "min", st[0], "max", st[1], "count", st[2]));
        }
        return out;
    }

    private List<Object> streamRows() {
        List<Object> out = new ArrayList<>(streams.size());
        for (Map.Entry<Long, Stream> en : streams.entrySet()) {
            Stream s = en.getValue();
            long[] merged = s.bytes.merged();
            byte[] prefixBytes = s.bytes.prefixBytes();
            out.add(Main.object("id", s.id, "high", s.high, "final", s.finalSize, "reset",
                    s.resetCode, "stop", s.stopCode, "send_max", s.sendMax, "ranges",
                    intervals(merged), "unique", s.bytes.unique(), "prefix", s.bytes.prefix(),
                    "sha256", sha256(prefixBytes, 0, prefixBytes.length)));
        }
        return out;
    }

    private List<Object> cryptoRows() {
        List<Object> out = new ArrayList<>(3);
        for (int l = 0; l < 3; l++) {
            ByteStore store = crypto[l];
            long[] merged = store.merged();
            byte[] prefixBytes = store.prefixBytes();
            out.add(Main.object("level", LEVEL[l], "ranges", intervals(merged), "unique",
                    store.unique(), "prefix", store.prefix(), "sha256",
                    sha256(prefixBytes, 0, prefixBytes.length)));
        }
        return out;
    }

    private List<Object> ackRows() {
        List<Object> out = new ArrayList<>(3);
        for (int l = 0; l < 3; l++) {
            AckLog log = ack[l];
            log.sort();
            long count = 0;
            long prefix = 0;
            int intervalCount = 0;
            ByteArrayOutputStream hash = new ByteArrayOutputStream();
            long start = -1;
            long end = -1;
            for (int i = 0; i < log.size(); i++) {
                long a = log.lo(i);
                long b = log.hi(i);
                if (start < 0) {
                    start = a;
                    end = b;
                } else if (a <= end) {
                    if (b > end) {
                        end = b;
                    }
                } else {
                    emit(hash, start, end);
                    intervalCount++;
                    count += end - start;
                    if (prefix == 0 && start == 0) {
                        prefix = end;
                    } else if (prefix > 0 && start <= prefix) {
                        prefix = end;
                    }
                    start = a;
                    end = b;
                }
            }
            if (start >= 0) {
                emit(hash, start, end);
                intervalCount++;
                count += end - start;
                if (prefix == 0 && start == 0) {
                    prefix = end;
                } else if (prefix > 0 && start <= prefix) {
                    prefix = end;
                }
            }
            byte[] bytes = hash.toByteArray();
            out.add(Main.object("level", LEVEL[l], "count", count, "intervals",
                    (long) intervalCount, "prefix", prefix, "sha256", sha256(bytes, 0, bytes.length),
                    "ecn", ecnRow(l)));
        }
        return out;
    }

    private static void emit(ByteArrayOutputStream hash, long start, long end) {
        for (int i = 7; i >= 0; i--) {
            hash.write((int) ((start >>> (8 * i)) & 255));
        }
        for (int i = 7; i >= 0; i--) {
            hash.write((int) ((end >>> (8 * i)) & 255));
        }
    }

    private List<Object> ecnRow(int level) {
        List<Object> out = new ArrayList<>(3);
        for (int i = 0; i < 3; i++) {
            out.add(ecn[level * 3 + i]);
        }
        return out;
    }

    private List<Object> peerRows() {
        List<Object> out = new ArrayList<>();
        for (Map.Entry<Long, PeerCid> en : peer.entrySet()) {
            if (en.getKey() < scal[S_THRESHOLD]) {
                continue;
            }
            out.add(Main.object("sequence", en.getKey(), "id", Main.hex(en.getValue().cid), "token",
                    Main.hex(en.getValue().token)));
        }
        return out;
    }

    private List<Object> retiredRows() {
        List<Object> out = new ArrayList<>();
        long start = -1;
        long end = -1;
        for (Long s : retiredLocal) {
            if (start < 0) {
                start = s;
                end = s + 1;
            } else if (s == end) {
                end = s + 1;
            } else {
                out.add(pair(start, end));
                start = s;
                end = s + 1;
            }
        }
        if (start >= 0) {
            out.add(pair(start, end));
        }
        return out;
    }

    private static List<Object> intervals(long[] merged) {
        List<Object> out = new ArrayList<>(merged.length / 2);
        for (int i = 0; i < merged.length; i += 2) {
            out.add(pair(merged[i], merged[i + 1]));
        }
        return out;
    }

    private static List<Object> pair(long a, long b) {
        List<Object> out = new ArrayList<>(2);
        out.add(a);
        out.add(b);
        return out;
    }

    static String sha256(byte[] data, int offset, int length) {
        try {
            MessageDigest md = MessageDigest.getInstance("SHA-256");
            md.update(data, offset, length);
            return Main.hex(md.digest());
        } catch (java.security.NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 unavailable", e);
        }
    }
